def transform(grid):
    import collections
    h, w = len(grid), len(grid[0])

    def build(axis):
        n = h if axis == 0 else w
        def get(i):
            return grid[i] if axis == 0 else [grid[r][i] for r in range(h)]
        flags = [len(set(get(i))) == 1 for i in range(n)]
        runs = []
        for i in range(n):
            if runs and flags[i] == runs[-1]['u']:
                runs[-1]['idx'].append(i)
            else:
                runs.append({'idx': [i], 'u': flags[i]})
        def runcolor(run):
            return get(run['idx'][0])[0]
        def rundom(run):
            cells = []
            for i in run['idx']:
                cells += get(i)
            return collections.Counter(cells).most_common(1)[0][0]
        changed = True
        while changed:
            changed = False
            for k in range(len(runs) - 1):
                a, b = runs[k], runs[k + 1]
                merge = False
                if a['u'] and b['u']:
                    merge = runcolor(a) == runcolor(b)
                elif a['u']:
                    merge = runcolor(a) == rundom(b)
                elif b['u']:
                    merge = runcolor(b) == rundom(a)
                if merge:
                    a['idx'] += b['idx']
                    del runs[k + 1]
                    changed = True
                    break
        blocks = [r['idx'] for r in runs if not r['u']]
        return blocks, get

    chosen = None
    for axis in (0, 1):
        blocks, get = build(axis)
        if len(blocks) == 2:
            chosen = (axis, blocks)
            break
    if chosen is None:
        return grid

    axis, blocks = chosen
    infos = []
    for idx in blocks:
        if axis == 0:
            cells = [grid[r][c] for r in idx for c in range(w)]
        else:
            cells = [grid[r][c] for r in range(h) for c in idx]
        cnt = collections.Counter(cells)
        dom, _ = cnt.most_common(1)[0]
        minority = [x for x in cells if x != dom]
        mc = collections.Counter(minority)
        mcol, mnum = mc.most_common(1)[0] if mc else (None, 0)
        infos.append({'idx': idx, 'dom': dom, 'mcol': mcol, 'mnum': mnum})

    infos.sort(key=lambda x: -x['mnum'])
    keep, drop = infos[0], infos[1]
    fill = drop['mcol']
    if fill is None:
        return [[keep['dom']] * (w if axis == 0 else len(keep['idx']))
                for _ in (range(h) if axis == 0 else range(1))]

    # local grids
    if axis == 0:
        kR, kC = keep['idx'], list(range(w))
        dR, dC = drop['idx'], list(range(w))
    else:
        kR, kC = list(range(h)), keep['idx']
        dR, dC = list(range(h)), drop['idx']
    dh, dw = len(dR), len(dC)

    def dcell(i, j):
        return grid[dR[i]][dC[j]]

    iso = set()
    for i in range(dh):
        for j in range(dw):
            if dcell(i, j) == fill:
                nbrs = [(i-1,j),(i+1,j),(i,j-1),(i,j+1)]
                if all(not (0 <= a < dh and 0 <= b < dw) or dcell(a, b) != fill
                       for a, b in nbrs):
                    iso.add((i, j))

    out = []
    for i in range(len(kR)):
        row = []
        for j in range(len(kC)):
            if (i, j) in iso and grid[kR[i]][kC[j]] == fill:
                row.append(3)
            else:
                row.append(fill)
        out.append(row)
    return out
